{
  "aggregate_id": "DEF-NRS-484A-320::vehicle",
  "classifications": [
    {
      "class": "ru.bicycle",
      "verdict": "supported",
      "reason": "The contract expressly describes a human-powered device, matching the human-power exception."
    },
    {
      "class": "ru.bus",
      "verdict": "supported",
      "reason": "A motor vehicle designed to carry passengers satisfies the transportation-device clause, and no exception describes that contract."
    },
    {
      "class": "ru.child",
      "verdict": "contradicted",
      "reason": "The contract describes a person rather than a device, and a wheelchair's capacity to transport that person does not make the person a device."
    },
    {
      "class": "ru.commercial_motor_vehicle",
      "verdict": "supported",
      "reason": "The transportation-device clause admits the contracted vehicle class, and no exception names or describes its commercial mass or licensing criteria."
    },
    {
      "class": "ru.electric_bicycle",
      "verdict": "underdetermined",
      "reason": "An assisting motor and a jurisdictional class attribute do not establish all the equipment, wattage and assistance limits required by the defined electric-bicycle exception."
    },
    {
      "class": "ru.electric_scooter",
      "verdict": "underdetermined",
      "reason": "The contract supplies handlebars, electric propulsion and riding position but does not establish the weight and motor-only speed limits required by the electric-scooter exception."
    },
    {
      "class": "ru.emergency_vehicle",
      "verdict": "supported",
      "reason": "The transportation-device clause admits the contracted vehicle class, and no exception removes vehicles because of their emergency designation."
    },
    {
      "class": "ru.fire_apparatus",
      "verdict": "supported",
      "reason": "A fire-fighting vehicle falls within the transportation-device clause, and no exception describes its fire-fighting designation."
    },
    {
      "class": "ru.moped",
      "verdict": "supported",
      "reason": "The admitting clause reaches jurisdiction-classed motor-driven mopeds, whose posted definition expressly distinguishes them from electric bicycles and electric scooters."
    },
    {
      "class": "ru.motor_vehicle",
      "verdict": "supported",
      "reason": "The self-propelled non-rail vehicle contract falls within the admitting clause and separates out the jurisdiction's separately classed powered two-wheelers."
    },
    {
      "class": "ru.motorcycle",
      "verdict": "supported",
      "reason": "A motor vehicle ridden astride transports a person and matches none of the stated exceptions."
    },
    {
      "class": "ru.official_vehicle",
      "verdict": "supported",
      "reason": "The transportation-device clause admits the contracted vehicle class, and no exception names or describes its official or contracted-service criteria."
    },
    {
      "class": "ru.pedestrian",
      "verdict": "contradicted",
      "reason": "Every alternative in the contract describes a person, not the wheelchair or other device transporting that person, so the device-only admitting clause reaches no member."
    },
    {
      "class": "ru.pedestrian_with_white_cane_or_guide_animal",
      "verdict": "contradicted",
      "reason": "The contract describes a pedestrian person with specified assistance, not a transporting device, so wheelchair characteristics do not create uncertainty about admission."
    },
    {
      "class": "ru.rail_vehicle",
      "verdict": "underdetermined",
      "reason": "The contract requires on-track equipment but does not require exclusive use upon stationary rails, leaving the exception's reach unsettled within the class."
    },
    {
      "class": "ru.school_bus",
      "verdict": "supported",
      "reason": "A bus designated to carry school children satisfies the transportation-device clause, and its designation triggers no exception."
    },
    {
      "class": "ru.taxicab",
      "verdict": "supported",
      "reason": "The passenger-transport contract satisfies the admitting clause, and no exception names or describes its for-hire markings criterion."
    },
    {
      "class": "ru.tour_bus_or_limousine",
      "verdict": "supported",
      "reason": "Both contracted alternatives are passenger-transport devices, and no exception describes their tour, shuttle or lengthened-for-hire characteristics."
    },
    {
      "class": "ru.trailer_or_combination",
      "verdict": "supported",
      "reason": "The contract permits both motor-drawn devices reached by the admitting clause and human-powered bicycle-drawn devices reached by the human-power exception without distinguishing them."
    },
    {
      "class": "ru.transit_bus",
      "verdict": "supported",
      "reason": "A bus in public transit service satisfies the transportation-device clause, and its service or identification features trigger no exception."
    },
    {
      "class": "ru.truck",
      "verdict": "supported",
      "reason": "A motor vehicle built to carry goods satisfies the property-transport clause and matches none of the stated exceptions."
    }
  ]
}

